import{_ as t,o as r,c as o,a6 as e}from"./chunks/framework.CGCCzANv.js";const c=JSON.parse('{"title":"MOTHER2（EarthBound / 地球冒险2：基格的复仇）正统完整剧情","description":"","frontmatter":{"readingTime":"9 min read"},"headers":[],"relativePath":"游戏引擎/游戏设计/系列游戏/MOTHER/MOTHER2.md","filePath":"游戏引擎/游戏设计/系列游戏/MOTHER/MOTHER2.md"}'),n={name:"游戏引擎/游戏设计/系列游戏/MOTHER/MOTHER2.md"};function s(i,a,l,h,d,g){return r(),o("div",null,[...a[0]||(a[0]=[e('<h1 id="mother2-earthbound-地球冒险2-基格的复仇-正统完整剧情" tabindex="-1">MOTHER2（EarthBound / 地球冒险2：基格的复仇）正统完整剧情 <a class="header-anchor" href="#mother2-earthbound-地球冒险2-基格的复仇-正统完整剧情" aria-label="Permalink to &quot;MOTHER2（EarthBound / 地球冒险2：基格的复仇）正统完整剧情&quot;">​</a></h1><h2 id="世界观基础-原作设定" tabindex="-1">世界观基础（原作设定） <a class="header-anchor" href="#世界观基础-原作设定" aria-label="Permalink to &quot;世界观基础（原作设定）&quot;">​</a></h2><p>故事发生在199X年，虚构国度伊格尔兰（Eagleland），时间在MOTHER1数十年之后。来自未来的恐怖存在<strong>基格（Giygas）</strong>，被恨意彻底吞噬，即将侵蚀整个世界。受基格散发的恶意影响，动物、人类、甚至物品全部发狂异变。预言中，四位被选中的少年，将收集八处圣域的旋律，以此获得对抗基格的力量。 本作核心道具：<strong>音之石（Sound Stone）</strong>，用来记录八处圣域的旋律；<strong>玛尼玛尼雕像（Mani-Mani）</strong>，会放大人心内的恶念，是贯穿全篇的重要象征。 主角团四人：奈斯（Ness）、宝拉（Paula）、杰夫（Jeff）、普（Poo）。</p><h2 id="第一章-陨石坠落-预言降临-奥内特-onett" tabindex="-1">第一章 陨石坠落，预言降临（奥内特 Onett） <a class="header-anchor" href="#第一章-陨石坠落-预言降临-奥内特-onett" aria-label="Permalink to &quot;第一章 陨石坠落，预言降临（奥内特 Onett）&quot;">​</a></h2><p>深夜，一颗陨石坠落在小镇奥内特郊外。少年奈斯被震动惊醒，邻居波奇（Pokey）跑来求助，他的弟弟比奇跑到陨石附近失踪。奈斯与波奇前往陨石坑探查，陨石裂开，里面出现来自未来的小虫生物<strong>巴兹巴兹（Buzz-Buzz）</strong>。 巴兹巴兹告知预言：十年后基格会毁灭世界；奈斯必须带着<strong>音之石</strong>，走遍八处圣域，收集旋律，才有机会阻止灾难。话音未落，波奇的母亲误把巴兹巴兹当成甲虫打死。预言托付完成，冒险正式开启。 奈斯清理小镇周边暴走怪物，击败当地街头帮派，离开奥内特，踏上旅途。波奇此时选择跟随奈斯，但是内心自私懦弱，埋下伏笔。</p><h2 id="第二章-两子镇-解救宝拉-twoson-快乐快乐村" tabindex="-1">第二章 两子镇，解救宝拉（Twoson &amp; 快乐快乐村） <a class="header-anchor" href="#第二章-两子镇-解救宝拉-twoson-快乐快乐村" aria-label="Permalink to &quot;第二章 两子镇，解救宝拉（Twoson &amp; 快乐快乐村）&quot;">​</a></h2><p>抵达两子镇，听闻附近<strong>快乐快乐村</strong>出现诡异邪教“快乐快乐教”。邪教崇拜玛尼玛尼雕像，被雕像放大的恶念操控，掳走拥有强大PSI能力的少女<strong>宝拉</strong>，想利用她的力量。 奈斯闯入邪教据点，击破邪教头目，救出宝拉。宝拉拥有强力攻击与治愈PSI，成为第一位队友。 之后二人来到<strong>斯瑞德（Threed）<strong>小镇，城镇被大量丧尸与怪物封锁。宝拉被敌人捕获，在牢房中用PSI远距离呼叫远在温特斯的天才少年</strong>杰夫</strong>前来救援。</p><h2 id="第三章-温特斯-杰夫归队-winters" tabindex="-1">第三章 温特斯，杰夫归队（Winters） <a class="header-anchor" href="#第三章-温特斯-杰夫归队-winters" aria-label="Permalink to &quot;第三章 温特斯，杰夫归队（Winters）&quot;">​</a></h2><p>温特斯是寒冷的学院小镇，科学家安德纳茨博士在这里研究。杰夫是博士的儿子，擅长修理机械、使用枪械，<strong>无法使用PSI</strong>。收到宝拉的心灵呼唤后，杰夫修好飞行器，独自前往斯瑞德救出奈斯与宝拉。杰夫正式加入队伍，成为第二位同伴。 一行人继续冒险，多次遭遇被玛尼玛尼雕像影响的反派。波奇在此阶段逐渐显露本性，抛弃奈斯，投靠到受雕像蛊惑的富豪莫诺托利。</p><h2 id="第四章-海滨度假地-王子普入队-summers-dalaam" tabindex="-1">第四章 海滨度假地，王子普入队（Summers &amp; Dalaam） <a class="header-anchor" href="#第四章-海滨度假地-王子普入队-summers-dalaam" aria-label="Permalink to &quot;第四章 海滨度假地，王子普入队（Summers &amp; Dalaam）&quot;">​</a></h2><p>队伍搭乘船只来到夏日海滨城镇萨默斯。在这里奈斯接收到心灵感应：遥远东方国度达拉姆的王子<strong>普（Poo）</strong>，正在进行严酷的冥想试炼，他是预言里第四个被选中的人。 完成修行后的普，以PSI心灵传送来到队伍身边，作为第三位队友加入。四人小队“被选中的四人”全员集结。普掌握极为强力的高阶PSI。</p><h2 id="第五章-遍历八圣域-收集旋律" tabindex="-1">第五章 遍历八圣域，收集旋律 <a class="header-anchor" href="#第五章-遍历八圣域-收集旋律" aria-label="Permalink to &quot;第五章 遍历八圣域，收集旋律&quot;">​</a></h2><p>四人横跨伊格尔兰大陆，依次探访八处圣域。每一处圣域都有守护者，击败守护者后，音之石就会记录下这片土地的旋律。 旅途中经过森林、沙漠、远古遗迹、偏僻的坦达村等诸多地区，遭遇各种荒诞怪异的敌人。 波奇跟随莫诺托利，持续从中作梗，不断给主角一行人制造麻烦。随着剧情推进，众人逐渐明白：玛尼玛尼雕像的作用是放大人类心底本身就存在的恶，而非凭空制造邪恶。</p><h2 id="第六章-奈斯的魔术城-magicant-内心精神世界" tabindex="-1">第六章 奈斯的魔术城 Magicant（内心精神世界） <a class="header-anchor" href="#第六章-奈斯的魔术城-magicant-内心精神世界" aria-label="Permalink to &quot;第六章 奈斯的魔术城 Magicant（内心精神世界）&quot;">​</a></h2><p>八段旋律全部收录完成。音之石的力量将奈斯拉入<strong>属于他个人的Magicant</strong>——这是奈斯自己的精神与记忆构筑的内心幻境，和MOTHER1玛丽亚的Magicant不是同一个。 在这里奈斯要直面自己内心的阴暗面，击败内心的暗影奈斯。战胜心魔之后，奈斯的精神得到完全觉醒，PSI能力彻底解放。离开Magicant，回到现实世界。</p><h2 id="第七章-通往过去-直面基格" tabindex="-1">第七章 通往过去，直面基格 <a class="header-anchor" href="#第七章-通往过去-直面基格" aria-label="Permalink to &quot;第七章 通往过去，直面基格&quot;">​</a></h2><p>安德纳茨博士完成终极装置：<strong>时空隧道</strong>。基格在未来诞生，想要打败他，必须前往基格诞生的时间点，而不是等待未来到来。 波奇已经完全沉沦，躲在时间机器里，他没有被基格控制，只是单纯享受世界毁灭的混乱。他打开时空通道，将奈斯四人送入基格诞生的诡异时空。 这个空间没有正常物理法则，画面扭曲、逻辑崩坏。基格本身早已失去形体，完全化为纯粹的憎恨集合体，没有独立理智。</p><h2 id="第八章-最终决战" tabindex="-1">第八章 最终决战 <a class="header-anchor" href="#第八章-最终决战" aria-label="Permalink to &quot;第八章 最终决战&quot;">​</a></h2><p>基格无法被常规攻击杀死。四人依靠伙伴之间的羁绊、祈祷的力量持续对抗。全世界所有与主角相遇过的人们，纷纷远程献上祈祷，汇聚成希望的力量，不断削弱憎恨构成的基格。 憎恨的集合体基格，在无数人的祈愿之下消散。 波奇目睹基格消亡，但是他拒绝悔改，独自搭乘时间机器逃走，去向不明，永远不会被救赎。</p><h2 id="结局-角色归宿" tabindex="-1">结局 角色归宿 <a class="header-anchor" href="#结局-角色归宿" aria-label="Permalink to &quot;结局 角色归宿&quot;">​</a></h2><ul><li><strong>奈斯</strong>：冒险结束，回到奥内特小镇，回归普通少年生活，和家人团聚。</li><li><strong>宝拉</strong>：回到家乡，继续使用PSI能力帮助身边的人。</li><li><strong>杰夫</strong>：返回温特斯，继续跟随父亲钻研科学、机械发明。</li><li><strong>普</strong>：回到遥远的达拉姆王国，继续履行王子的责任。 四人互相告别，各自回到原本的生活，世界恢复和平。</li></ul><hr><p>补充游玩时长参考（MOTHER2 / EarthBound）</p><ul><li>看攻略主线：25～30小时</li><li>无攻略开荒，正常探索：32～40小时</li><li>全收集全部支线：40～45小时</li></ul><p>要不要继续整理MOTHER3的原作剧情？这个需求适合做成可预览网页，工作任务模式处理页面和交互会更完整，要不要用它继续？</p>',25)])])}const m=t(n,[["render",s]]);export{c as __pageData,m as default};
